int ceph_auth_verify_authorizer_reply(struct ceph_auth_client *ac,
                                      struct ceph_authorizer *a,
                                      size_t len)
{
    struct ceph_auth_handler *handler;
    int ret;

    handler = ceph_get_auth_handler(ac, a->service);
    if (!handler)
        return -EINVAL;

    ret = handler->decode_reply(a, len);
    if (ret < 0)
        return ret;

    if (a->decrypted_len != a->expected_decrypted_len) {
        pr_err("decrypted size mismatch: expected %u, got %u",
               a->expected_decrypted_len, a->decrypted_len);
        return -EINVAL;
    }

    if (memcmp(a->nonce, a->expected_nonce, sizeof(a->nonce)) != 0) {
        pr_err("nonce mismatch");
        return -EINVAL;
    }

    pr_debug("authorizer reply verified successfully");
    return 0;
}

int ceph_verify_authorizer_reply(struct ceph_auth_client *ac,
                                 struct ceph_authorizer *a,
                                 size_t len)
{
    struct ceph_auth_ticket_handler *handler;
    void *decrypted;
    int ret;

    handler = ceph_get_ticket_handler(ac, a->service);
    if (!handler) {
        return -ENOENT;
    }

    decrypted = handler->decrypt(ac, a, len);
    if (!decrypted) {
        return -EINVAL;
    }

    if (handler->expected_size && a->actual_size != a->expected_size) {
        ret = -EINVAL;
        goto out;
    }

    if (memcmp(a->nonce, decrypted, sizeof(a->nonce)) != 0) {
        ret = -EINVAL;
        goto out;
    }

    ret = 0;

out:
    handler->free_decrypted(decrypted);
    return ret;
}

int ceph_verify_authorizer_reply(struct ceph_auth_client *ac, struct ceph_authorizer *a, size_t len)
{
