    handler = ceph_get_ticket_handler(ac, a->service);
    if (!handler) {
        return -EINVAL;
    }

    ret = ceph_decrypt_reply(handler->session_key, a->reply, len, a->decrypted_reply, &a->decrypted_len);
    if (ret < 0) {
        return ret;
    }

    if (a->decrypted_len != a->expected_decrypted_len) {
        return -EBADMSG;
    }

    if (memcmp(a->nonce, a->decrypted_nonce, sizeof(a->nonce)) != 0) {
        return -EINVAL;
    }

    CEPH_LOG_DEBUG("Authorizer reply verification successful.");
    return 0;
}

int ceph_auth_verify_authorizer_reply(struct ceph_auth_client *ac,
                                      struct ceph_authorizer *a,
                                      size_t len)
{
    struct ceph_auth_ticket_handler *th;
    int ret;

    th = ceph_auth_get_ticket_handler(ac, a->service);
    if (!th) {
        return -ENOENT;
    }

    ret = ceph_auth_decrypt(ac, a->reply_data, len, th->session_key, &a->decrypted_data);
    if (ret < 0) {
        return ret;
    }

    if (a->decrypted_data.size != a->expected_decrypted_size) {
        return -EBADMSG;
    }

    if (memcmp(a->decrypted_nonce, a->expected_nonce, sizeof(a->decrypted_nonce)) != 0) {
        return -EINVAL;
    }

    ceph_log_debug("Authorizer reply verified for service %s", a->service);

    return 0;
}

